def compact_doc(*, slug, title, question, opening_title, opening, hotel, advance, defer,
                units, instrument_title, instrument_fields, transfer_title, transfer,
                counter_title, counter, errors, referents, references):
    movements=[]
    for i, movement_title in enumerate([
        "Movimiento 1 · Reconocer condiciones antes de prescribir",
        "Movimiento 2 · Diseñar opciones con evidencia y autoridad",
        "Movimiento 3 · Gobernar transición, aprendizaje y retiro",
    ]):
        movements.append([movement_title, units[i*4:(i+1)*4]])
    return {
        "slug":slug,"title":title,"question":question,"opening_title":opening_title,
        "opening":opening,"hotel":hotel,"advance":advance,"defer":defer,"movements":movements,
        "instrument_title":instrument_title,"instrument_fields":instrument_fields,
        "transfer_title":transfer_title,"transfer":transfer,"counter_title":counter_title,"counter":counter,
        "errors":errors,"consequences":advance+" Esta capacidad permite discutir costo, riesgo y responsabilidad sin esconder decisiones detrás de una etiqueta técnica.",
        "limits":"La evidencia nunca elimina por completo el juicio. Restricciones legales, relaciones de poder, capacidad operativa y costos hundidos reducen el espacio de opciones. El instrumento debe hacer visibles esas condiciones y conservar una vía de revisión, no prometer neutralidad.",
        "pills":[u[1] for u in units[:5]],
        "glossary":[[u[0],u[1][0].lower()+u[1][1:]] for u in units[:12]],
        "questions":[f"¿Qué decisión permite sostener {u[0].lower()} y qué evidencia podría refutarla?" for u in units[:6]],
        "referents":referents,"references":references,
    }


