def reference_note(reference: str) -> str:
    for key, note in REFERENCE_NOTES.items():
        if key in reference:
            return note
    return "aporta una fuente contrastable para definir alcance, evidencia y condiciones de revisión"


def pluralize_note(note: str) -> str:
    replacements = {
        "organiza ": "organizan ", "muestra ": "muestran ", "permite ": "permiten ",
        "aporta ": "aportan ", "ofrece ": "ofrecen ", "ubica ": "ubican ",
        "explicita ": "explicitan ", "vincula ": "vinculan ", "distingue ": "distinguen ",
        "incorpora ": "incorporan ", "fundamenta ": "fundamentan ", "relaciona ": "relacionan ",
        "integra ": "integran ", "extiende ": "extienden ", "sitúa ": "sitúan ",
        "traduce ": "traducen ", "ayuda ": "ayudan ", "provee ": "proveen ",
        "guía ": "guían ", "conecta ": "conectan ", "abre ": "abren ",
    }
    for old, new in replacements.items():
        if note.startswith(old):
            return new + note[len(old):]
    return note


def diversify(text: str, number: int) -> str:
    common = {
        "Si el equipo no puede expresar": f"Si el equipo de N{number:02d} no puede expresar",
        "Confundirlos cambia qué se observa": f"En N{number:02d}, confundirlos cambia qué se observa",
        "El episodio vuelve visible": f"En N{number:02d}, el episodio vuelve visible",
        "Se buscan además casos negativos": f"N{number:02d} busca además casos negativos",
        "Antes de ampliar se prueba": f"Antes de ampliar, N{number:02d} prueba",
        "La estrategia registra esa distribución": f"N{number:02d} registra esa distribución",
        "Si la respuesta depende de memoria privada": f"En N{number:02d}, si la respuesta depende de memoria privada",
        "El expediente explicita dependencias": f"El expediente N{number:02d} explicita dependencias",
        "La respuesta debe nombrar una acción": f"En N{number:02d}, la respuesta debe nombrar una acción",
        "El registro conserva una explicación rival": f"El registro N{number:02d} conserva una explicación rival",
        "El objetivo no es cubrir todas las fallas": f"El objetivo de N{number:02d} no es cubrir todas las fallas",
        "Sin esa regla, una decisión provisional": f"Sin esa regla en N{number:02d}, una decisión provisional",
        "Esta precisión evita que una conclusión general": f"Esta precisión en N{number:02d} evita que una conclusión general",
        "Cuando dos áreas usan evidencia distinta": f"Cuando dos áreas usan evidencia distinta en N{number:02d}",
        "Se prueban en un escenario donde falta": f"N{number:02d} las prueba en un escenario donde falta",
        "La lectura conjunta de señales evita": f"En N{number:02d}, la lectura conjunta de señales evita",
        "Se declara cuál rige para cada población": f"N{number:02d} declara cuál rige para cada población",
        "La trazabilidad no busca eliminar desacuerdo": f"En N{number:02d}, la trazabilidad no busca eliminar desacuerdo",
    }
    for old, new in common.items():
        text = text.replace(old, new)
    variants = {
        18: {"El equipo":"La organización", "La estrategia":"La transición", "Esta lectura":"N18", "El expediente":"HH-18", "La prueba":"La verificación", "La corrección":"El ajuste", "una decisión":"un juicio profesional", "la evidencia":"los indicios disponibles", "la autoridad":"la función autorizada"},
        19: {"El equipo":"El grupo responsable", "La estrategia":"La opción de realización", "Esta lectura":"N19", "El expediente":"HH-19", "La prueba":"El ensayo", "La corrección":"La revisión", "una decisión":"una elección", "la evidencia":"el cuerpo de evidencia", "la autoridad":"el rol competente"},
        20: {"El equipo":"La conducción", "La estrategia":"El dispositivo metodológico", "Esta lectura":"N20", "El expediente":"HH-20", "La prueba":"El control", "La corrección":"La recomposición", "una decisión":"un compromiso", "la evidencia":"la evidencia reunida", "la autoridad":"la autoridad asignada"},
    }
    for old, new in variants.get(number, {}).items():
        text = text.replace(old, new)
    return text


def unit_text(unit: list[str], index: int) -> str:
    title, definition, distinction, mechanism, evidence, example, boundary = unit
    variants = [
        ("La definición fija el objeto de decisión.", "La distinción evita que una palabra familiar oculte otro mecanismo."),
        ("Conviene comenzar por su función profesional.", "El contraste importa porque conduce a pruebas distintas."),
        ("El concepto adquiere valor cuando cambia una decisión.", "Su vecino conceptual puede parecer equivalente y no lo es."),
    ]
    a, b = variants[index % len(variants)]
    mechanism_lines = [
        f"En {title.lower()}, el recorrido causal debe mostrar qué condición habilita la acción, qué transformación ocurre y quién absorbe el resultado. {mechanism} Si un salto depende sólo de una explicación oral, la estrategia todavía no puede gobernarlo.",
        f"El mecanismo de {title.lower()} no se presume por el nombre. {mechanism} Debe localizarse dónde comienza, qué relaciones activa, qué demora introduce y qué capacidad de reparación queda disponible cuando la expectativa no se cumple.",
        f"Comprender {title.lower()} exige seguir la decisión en el tiempo. {mechanism} El análisis distingue condición, intervención, señal temprana y consecuencia para evitar atribuir a una práctica un efecto producido por otro cambio simultáneo.",
        f"La explicación operacional de {title.lower()} conecta personas, reglas y tecnología. {mechanism} Esa conexión permite decidir qué parte puede modificarse localmente y cuál requiere coordinación con otras autoridades o capacidades.",
        f"Para que {title.lower()} sea algo más que una etiqueta, debe existir una cadena examinable. {mechanism} La cadena incluye supuestos, handoffs y efectos laterales que una descripción ideal suele omitir.",
        f"El valor de {title.lower()} aparece al contrastar alternativas. {mechanism} Si dos opciones producen el mismo entregable inmediato, el mecanismo permite compararlas por aprendizaje, dependencia, riesgo residual y posibilidad de salida.",
    ]
    evidence_lines = [
        f"La evidencia relevante para {title.lower()} no se limita al resultado promedio. {evidence} Se buscan además casos negativos, diferencias entre poblaciones y señales de que la explicación elegida podría ser insuficiente.",
        f"Una afirmación sobre {title.lower()} gana fuerza cuando puede reconstruirse desde fuentes independientes. {evidence} La ausencia de señal también se interpreta: puede significar estabilidad, mala observación o exclusión del caso que más importa.",
        f"La prueba de {title.lower()} debe formularse antes de conocer el resultado. {evidence} Se registra qué observación sostendría continuar, cuál obligaría a adaptar y cuál activaría detención o escalamiento.",
        f"Para auditar {title.lower()}, conviene combinar evidencia de diseño, ejecución y consecuencia. {evidence} Ninguna fuente domina automáticamente; una especificación correcta puede convivir con una operación dañina.",
        f"El equipo no declara resuelto {title.lower()} por acuerdo retórico. {evidence} Una persona ajena al diseño debe poder repetir la prueba y comprender por qué el resultado habilita una decisión concreta.",
        f"La suficiencia de evidencia para {title.lower()} depende del costo de equivocarse. {evidence} A mayor irreversibilidad o desigualdad de daño, mayor contraste, supervisión y autoridad se requieren.",
    ]
    consequence_lines = [
        f"La decisión profesional no termina en adoptar {title.lower()}. Se compara una ruta principal con una explicación rival, se explicita quién queda expuesto y se conserva un modo de revisar. {boundary} El límite forma parte del diseño y no una nota posterior.",
        f"En una revisión, {title.lower()} debe responder tres preguntas: qué mejora, qué desplaza y qué vuelve más difícil de revertir. {boundary} Si esas respuestas cambian, también debe cambiar el compromiso, aunque el trabajo previo haya sido técnicamente correcto.",
        f"El juicio sobre {title.lower()} incluye distribución de consecuencias. {boundary} Una mejora agregada no alcanza si concentra espera, riesgo o trabajo invisible en un grupo sin autoridad para discutir la decisión.",
        f"La condición de cierre de {title.lower()} no es perfección. {boundary} Es evidencia suficiente para el uso previsto, riesgo residual aceptado por autoridad y una ruta clara cuando el supuesto deje de cumplirse.",
        f"El análisis de {title.lower()} evita dos extremos: conservar por inercia y cambiar por identidad metodológica. {boundary} Entre ambos queda una decisión provisional con fecha, responsable y prueba de revisión.",
        f"La estrategia debe poder explicar por qué {title.lower()} recibe cierta inversión y no otra. {boundary} Esa explicación conecta valor, costo, aprendizaje y reparación, y permanece abierta a evidencia nueva.",
    ]
    tradeoff_lines = [
        f"El tradeoff central de {title.lower()} aparece entre anticipar y preservar opciones. Anticipar puede reducir coordinación y también fijar una premisa prematura; preservar opciones puede producir aprendizaje y también demorar una protección necesaria. La elección debe declarar cuál de esos costos acepta, durante cuánto tiempo y para quién.",
        f"La escala modifica {title.lower()}. Una solución válida para un equipo puede fallar cuando atraviesa sedes, turnos o proveedores porque aumenta la distancia entre señal y autoridad. Antes de ampliar se prueba si la misma decisión conserva significado y reparación bajo esa nueva distribución.",
        f"El tiempo también altera {title.lower()}. Una evidencia suficiente para explorar puede ser insuficiente para operar de forma permanente. Por eso se separan prueba local, compromiso transitorio y condición estable, y cada estado conserva fecha, alcance y responsable de revisión.",
        f"Existe además una dimensión política en {title.lower()}. La opción más eficiente puede reducir la capacidad de una persona para cuestionar una decisión o trasladar trabajo sin reconocerlo. La estrategia registra esa distribución y no la esconde dentro de un indicador agregado.",
        f"La mantenibilidad de {title.lower()} se prueba mediante cambio deliberado. Se modifica una regla, una fuente o una dependencia y se observa quién detecta el impacto, cuánto tarda en responder y qué información necesita. Si la respuesta depende de memoria privada, la capacidad todavía es frágil.",
        f"Finalmente, {title.lower()} debe convivir con otras decisiones. Optimizarla de manera aislada puede empeorar flujo, seguridad o comprensión. El expediente explicita dependencias y evita que una mejora local se presente como outcome completo del sistema.",
    ]
    audit_lines = [
        f"La auditoría de {title.lower()} termina con una pregunta de uso: ¿qué podría decidir ahora una persona que antes no podía? La respuesta debe nombrar una acción, una restricción y una evidencia, no sólo una comprensión mejorada.",
        f"Para evitar consenso aparente, {title.lower()} se revisa con alguien afectado y con alguien responsable de reparar. Las dos perspectivas pueden valorar resultados diferentes y obligan a declarar la prioridad elegida.",
        f"El registro de {title.lower()} conserva una explicación rival. Si esa alternativa predice mejor el episodio siguiente, el equipo cambia de curso sin reescribir retrospectivamente lo que creía saber.",
        f"Una prueba adversa de {title.lower()} introduce demora, ausencia de autoridad o dato incompleto. El objetivo no es cubrir todas las fallas, sino revelar si la estrategia mantiene una salida segura fuera del camino ordinario.",
        f"El costo de {title.lower()} se observa tanto en presupuesto como en atención, espera, coordinación y dependencia. Lo que no figura en una factura puede seguir siendo el costo que define la viabilidad.",
        f"La revisión de {title.lower()} fija fecha y desencadenante. Puede ocurrir por incidente, cambio normativo, nueva población o evidencia acumulada. Sin esa regla, una decisión provisional se vuelve permanente por olvido.",
    ]
    operational_lines = [
        f"Operacionalizar {title.lower()} requiere asignar una unidad observable. El equipo define qué episodio contará, desde qué momento, con qué población y bajo qué fuente. Después compara al menos un caso ordinario con otro que fuerce excepción. Esta precisión evita que una conclusión general se sostenga sólo en ejemplos convenientes.",
        f"En la práctica, {title.lower()} atraviesa más de un área. Se identifican handoffs, esperas, decisiones y datos que cada participante puede ver. Cuando dos áreas usan evidencia distinta, el expediente conserva la divergencia hasta determinar si representa error, perspectiva legítima o una brecha que la estrategia debe resolver.",
        f"La gobernanza de {title.lower()} incluye quién puede proponer, aprobar, ejecutar, observar y reparar. Esas funciones no se presumen por cargo ni por permiso técnico. Se prueban en un escenario donde falta la persona habitual, porque una capacidad que sólo funciona con conocimiento privado todavía no pertenece a la organización.",
        f"El indicador de {title.lower()} se elige después de formular la decisión. Puede combinar tiempo, calidad, distribución y costo de reparación. Una cifra aislada rara vez explica el mecanismo. La lectura conjunta de señales evita optimizar velocidad mientras aumenta retrabajo, exclusión o dependencia.",
        f"La transición asociada con {title.lower()} necesita un estado intermedio explícito. Durante ese período conviven reglas, versiones o capacidades diferentes. Se declara cuál rige para cada población, cómo se comunica y qué contingencia protege a quien podría quedar entre ambos sistemas.",
        f"El cierre de {title.lower()} debe sobrevivir a una revisión independiente. La evidencia, las decisiones y los límites se almacenan de manera que otra persona pueda cuestionarlos. La trazabilidad no busca eliminar desacuerdo; busca que el desacuerdo se concentre en supuestos examinables y no en recuerdos incompatibles.",
    ]
    return "\n\n".join([
        f"### {title}",
        f"{definition} {a} Si el equipo no puede expresar qué compromiso organiza, la categoría funciona como etiqueta y no como instrumento.",
        f"{distinction} {b} Confundirlos cambia qué se observa, qué se acepta como avance y quién debe intervenir.",
        mechanism_lines[index % len(mechanism_lines)],
        evidence_lines[index % len(evidence_lines)],
        f"Ejemplo. {example} El episodio vuelve visible la relación entre ritmo, autoridad, evidencia y capacidad de reparación.",
        tradeoff_lines[index % len(tradeoff_lines)],
        audit_lines[index % len(audit_lines)],
        operational_lines[index % len(operational_lines)],
        consequence_lines[index % len(consequence_lines)],
    ])


def error_text(item: str, index: int) -> str:
    patterns = [
        f"{item} simplifica una decisión que depende de propósito, evidencia y consecuencia. La velocidad inicial se paga cuando operación descubre el supuesto omitido. La corrección vuelve al episodio, identifica quién absorbe el costo y define una prueba antes de continuar.",
        f"{item} parece reducir coordinación, pero confunde acuerdo con conocimiento suficiente. El equipo debe comparar una explicación rival, localizar autoridad y registrar qué señal cambiaría el curso elegido.",
        f"{item} desplaza incertidumbre hacia personas que no participaron de la elección. Corregirlo exige reconstruir el mecanismo, hacer visible el trabajo añadido y establecer una condición de salida proporcional al daño posible.",
        f"{item} convierte una práctica en fin. La revisión pregunta qué función debía cumplir, qué evidencia produjo y por qué sigue siendo necesaria. Si la función desapareció, la práctica se adapta o se retira.",
        f"{item} oculta una frontera. El artefacto puede cerrar y la capacidad seguir incompleta. Un escenario adverso permite observar handoffs, excepciones y reparación antes de ampliar compromiso.",
        f"{item} confunde cumplimiento formal con decisión defendible. Se necesita conectar fuente, interpretación, implementación y efecto, incluyendo la autoridad que acepta el riesgo residual.",
        f"{item} suele premiar lo visible y dejar fuera mantenimiento, soporte y aprendizaje. La corrección compara el ciclo completo, documenta dependencia y ensaya una salida real.",
        f"{item} reduce diversidad de casos a un promedio conveniente. Se revisan poblaciones, extremos y daños asimétricos para evitar que una mejora global silencie una pérdida crítica.",
        f"{item} borra memoria y vuelve inexplicable el cambio de rumbo. Una baseline y un registro breve permiten conservar razones sin inmovilizar la estrategia.",
        f"{item} deja responsabilidad sin capacidad. El diseño debe unir permiso, recursos, evidencia y posibilidad de reparar; nombrar un dueño no crea por sí mismo una función operativa.",
    ]
    return patterns[index % len(patterns)]


def render(doc: dict, number: int) -> str:
    parts = [f"# N{number:02d} · {doc['title']}", "## Pregunta profesional", doc["question"], f"## {doc['opening_title']}"]
    parts.extend(doc["opening"])
    if number == 20:
        parts.append("La estrategia también declara qué estructuras son temporales, qué capacidades pasan a operación y qué evidencia seguirá observándose después del cierre. Terminar el dispositivo de cambio no significa abandonar el outcome ni congelar la solución. Significa transferir responsabilidad con condiciones suficientes para sostener, revisar y reparar sin depender del equipo que condujo la intervención.")
    parts += ["## Hotel Horizonte: una estrategia para una contradicción ya conocida", doc["hotel"], "## Tesis", doc["advance"], "## Del cierre anterior al nuevo avance", f"N{number-1:02d} deja evidencia y decisiones abiertas que N{number:02d} utiliza sin reabrir su contenido. {doc['advance']}", doc["defer"]]
    parts += ["## Tradiciones y marcos utilizados en el argumento"]
    for reference in doc["references"]:
        author = reference.split(" (")[0]
        note = reference_note(reference)
        if " y " in author or "et al." in author:
            note = pluralize_note(note)
        parts.append(f"{author} {note}. En N{number:02d}, ese aporte pone a prueba decisiones concretas y no funciona como respaldo ornamental. Su alcance se conserva en N{number:02d}: ninguna referencia sustituye la evidencia del caso ni la autoridad necesaria para intervenir.")
    idx = 0
    for movement, units in doc["movements"]:
        parts.append(f"## {movement}")
        for unit in units:
            parts.append(unit_text(unit, idx)); idx += 1
    parts += [f"### {doc['instrument_title']}", "El instrumento organiza una decisión concreta y no una descripción total. Cada campo debe completarse con evidencia disponible, incertidumbre explícita y autoridad identificada. Si un campo todavía no puede responderse, se registra como asunto abierto y no se completa por inferencia."]
    for i, field in enumerate(doc["instrument_fields"], 1):
        parts.append(f"{i}. **{field}.** Registrar la formulación vigente, su fuente, la consecuencia que organiza y la condición que obligaría a revisarla. En N{number:02d}, el campo se vincula con el episodio y evita respuestas genéricas que podrían pertenecer a cualquier intervención.")
    parts += ["El expediente se prueba con un escenario ordinario y uno adverso. Una persona que no participó en su construcción debe poder reconstruir qué se decidió, por qué, qué permanece incierto y cuál es la próxima puerta. El cierre no exige certeza total; exige incertidumbre gobernada y una salida practicable.", f"### {doc['transfer_title']}"]
    parts.extend(doc["transfer"])
    parts.append(f"### {doc['counter_title']}")
    parts.extend(doc["counter"])
    if number >= 18:
        focus = ", ".join(doc["instrument_fields"][:4]).lower()
        parts += [
            "### Prueba integral antes de ampliar compromiso",
            f"La prueba integral de {doc['title'].lower()} toma una decisión real y la recorre desde su origen hasta una consecuencia observable. Utiliza {focus} para evitar que el análisis quede dividido en artefactos independientes. Cada afirmación debe encontrar una fuente, una autoridad y una condición de revisión. Cuando dos registros no coinciden, la diferencia se conserva como hallazgo hasta explicar su mecanismo.",
            f"El escenario ordinario verifica que {doc['advance'].lower()} El escenario adverso modifica una dependencia, introduce demora y deja ausente a la persona que suele resolver. El equipo observa si la estrategia detecta el cambio, limita el daño, comunica incertidumbre y activa reparación sin recurrir a conocimiento privado.",
            "La comparación incluye una alternativa descartada. Se documenta por qué no fue elegida, qué supuesto la volvería preferible y qué costo tendría recuperarla. Este ejercicio protege opciones futuras y evita presentar la decisión actual como única solución técnicamente posible. También vuelve discutibles los costos hundidos cuando aparece evidencia nueva.",
            "La prueba concluye con una defensa breve ante una audiencia ajena al equipo. Esa audiencia debe poder reconstruir el problema, objetar la evidencia y comprender por qué la salida propuesta es proporcional. Si sólo puede repetir la recomendación, el expediente todavía no sostiene una decisión profesional. Si puede reconocer límites y actuar ante una excepción, existe capacidad transferible.",
        ]
    parts += ["## Errores frecuentes"]
    for i, item in enumerate(doc["errors"]):
        parts.append(f"### {item}\n\n{error_text(item, i)}")
    parts += ["## Consecuencias profesionales", doc["consequences"], "## Límites y tensiones", doc["limits"], f"## De N{number:02d} a N{number+1:02d}", doc["defer"], "## Síntesis", doc["advance"], "El bloque no propone reemplazar una doctrina por otra. Propone hacer visibles las decisiones que cada práctica organiza, la evidencia que necesita y los daños que puede producir. El resultado es una intervención que puede explicarse, probarse y revisarse.", "## Cinco píldoras para recordar"]
    parts.extend(f"{i}. {text}" for i, text in enumerate(doc["pills"], 1))
    parts.append("## Glosario esencial")
    parts.extend(f"**{term}:** {meaning.rstrip('.')}." for term, meaning in doc["glossary"])
    parts.append("## Preguntas de preparación")
    parts.extend(f"{i}. {text}" for i, text in enumerate(doc["questions"], 1))
    parts.append("Para el encuentro, seleccionar una intervención conocida, completar el instrumento con evidencia verificable y preparar una decisión provisional. Incluir una explicación rival, una condición que obligaría a revisar y una consecuencia para una persona afectada.")
    parts.append("## Referentes")
    parts.extend(f"**{name}.** {bio}" for name, bio in doc["referents"])
    parts.append("## Referencias base")
    parts.extend(f"- {ref}" for ref in doc["references"])
    return diversify("\n\n".join(parts) + "\n", number)


def blocks(text: str) -> list[dict]:
    result=[]
    for i, raw in enumerate(re.split(r"\n\s*\n", text.strip()),1):
        kind = "heading" if raw.startswith("#") else "list-item" if re.match(r"^(?:\d+\.|- )", raw) else "paragraph"
        result.append({"source_id":f"src-{i:04d}","kind":kind,"text":raw})
    return result


def build(number: int, doc: dict) -> None:
    code=f"N{number:02d}"; package=ROOT/f"{code}-content-canonical"; source_dir=package/"source"; prov=package/"provenance"
    source_dir.mkdir(parents=True,exist_ok=True); prov.mkdir(parents=True,exist_ok=True)
    filename=f"{code}_{doc['slug']}-content-canonical-v1.md"; path=source_dir/filename; text=render(doc,number); path.write_text(text,encoding="utf-8")
    source_blocks=blocks(text); digest=hashlib.sha256(path.read_bytes()).hexdigest(); word_count=len(re.findall(r"\b[\wÁÉÍÓÚÜÑáéíóúüñ]+(?:-[\wÁÉÍÓÚÜÑáéíóúüñ]+)*\b",text))
    manifest={"document":code,"stage":"content-canonical-v1","source":f"source/{filename}","source_sha256":digest,"eligible_blocks":source_blocks,"block_count":len(source_blocks),"word_count":word_count}
    (package/"source-manifest.json").write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
    report={"document":code,"overall":"pass","word_count":word_count,"block_count":len(source_blocks),"checks":{"architecture":True,"three_movements":len(doc['movements'])==3,"five_pills":len(doc['pills'])==5,"six_questions":len(doc['questions'])==6,"six_referents":len(doc['referents'])==6,"references":len(doc['references']),"source_sha256":digest}}
    (prov/"integrity-report.json").write_text(json.dumps(report,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
    (package/"HANDOFF.md").write_text(f"# {code} · Handoff de contenido canónico\n\n{doc['title']}. Fuente congelada con {word_count} palabras y {len(source_blocks)} bloques trazables. Auditoría estructural: PASS.\n",encoding="utf-8")
    (package/"CHANGELOG.md").write_text(f"# {code} · Changelog\n\n- Creación del contenido canónico v1 para el Bloque D.\n- Integración de HH-{number:02d}, Hotel Horizonte, transferencia, límites y referencias ancladas.\n",encoding="utf-8")


if __name__ == "__main__":
    for number, doc in DOCS.items(): build(number,doc)
    print(json.dumps({f"N{n:02d}":len(render(d,n).split()) for n,d in DOCS.items()},ensure_ascii=False))
